#include <cuda_runtime.h>

__global__ void gemm_kernel(const float* lhs, const float* rhs, float* output, int m, int n, int k) {
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    if (row >= m || col >= n) return;
    float sum = 0.0f;
    for (int inner = 0; inner < k; ++inner) {
        sum += lhs[row * k + inner] * rhs[inner * n + col];
    }
    output[row * n + col] = sum;
}

extern "C" void gemm_launcher(
    const float* lhs, const float* rhs, float* output, int m, int n, int k, void* stream_handle) {
    auto stream = static_cast<cudaStream_t>(stream_handle);
    dim3 block(16, 16);
    dim3 grid((n + block.x - 1) / block.x, (m + block.y - 1) / block.y);
    gemm_kernel<<<grid, block, 0, stream>>>(lhs, rhs, output, m, n, k);
}
