#include <cuda_runtime.h>

__global__ void rms_norm_kernel(const float* input, float* output, int rows, int cols, float eps) {
    int row = blockIdx.x;
    if (row >= rows) return;
    __shared__ float scratch[256];
    float sum_sq = 0.0f;
    for (int col = threadIdx.x; col < cols; col += blockDim.x) {
        float value = input[row * cols + col];
        sum_sq += value * value;
    }
    scratch[threadIdx.x] = sum_sq;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) scratch[threadIdx.x] += scratch[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) scratch[0] = rsqrtf(scratch[0] / static_cast<float>(cols) + eps);
    __syncthreads();
    float inv_rms = scratch[0];
    for (int col = threadIdx.x; col < cols; col += blockDim.x) {
        output[row * cols + col] = input[row * cols + col] * inv_rms;
    }
}

extern "C" void rms_norm_launcher(
    const float* input, float* output, int rows, int cols, float eps, void* stream_handle) {
    auto stream = static_cast<cudaStream_t>(stream_handle);
    rms_norm_kernel<<<rows, 256, 0, stream>>>(input, output, rows, cols, eps);
}
