#include <cuda_runtime.h>

__global__ void conv2d_kernel(
    const float* input, const float* weight, float* output,
    int batch, int in_channels, int height, int width,
    int out_channels, int kernel_h, int kernel_w, int padding,
    int out_h, int out_w) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * out_channels * out_h * out_w;
    if (index >= total) return;
    int ow = index % out_w;
    int value = index / out_w;
    int oh = value % out_h;
    value /= out_h;
    int oc = value % out_channels;
    int n = value / out_channels;
    float sum = 0.0f;
    for (int ic = 0; ic < in_channels; ++ic) {
        for (int kh = 0; kh < kernel_h; ++kh) {
            int ih = oh + kh - padding;
            if (ih < 0 || ih >= height) continue;
            for (int kw = 0; kw < kernel_w; ++kw) {
                int iw = ow + kw - padding;
                if (iw < 0 || iw >= width) continue;
                int input_index = ((n * in_channels + ic) * height + ih) * width + iw;
                int weight_index = ((oc * in_channels + ic) * kernel_h + kh) * kernel_w + kw;
                sum += input[input_index] * weight[weight_index];
            }
        }
    }
    output[index] = sum;
}

extern "C" void conv2d_launcher(
    const float* input, const float* weight, float* output,
    int batch, int in_channels, int height, int width,
    int out_channels, int kernel_h, int kernel_w, int padding,
    int out_h, int out_w, void* stream_handle) {
    auto stream = static_cast<cudaStream_t>(stream_handle);
    int total = batch * out_channels * out_h * out_w;
    conv2d_kernel<<<(total + 255) / 256, 256, 0, stream>>>(
        input, weight, output, batch, in_channels, height, width,
        out_channels, kernel_h, kernel_w, padding, out_h, out_w);
}
